import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { getRequests } from '../services/requestService';
import { useAuth } from '../context/AuthContext';
import { toast } from 'react-toastify';

const RequestList = () => {
  const { user } = useAuth();
  const [requests, setRequests] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadRequests();
  }, []);

  const loadRequests = async () => {
    try {
      const data = await getRequests();
      setRequests(data);
    } catch (error) {
      toast.error('Erreur lors du chargement des demandes');
      setRequests([]);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div>
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-2xl font-bold">Liste des demandes</h1>
        <Link to="/requests/new" className="btn btn-primary">+ Nouvelle demande</Link>
      </div>
      <div className="card">
        {loading && <p>Chargement...</p>}

        {!loading && requests.length === 0 && (
          <p>Aucune demande trouvée.</p>
        )}

        {!loading && requests.length > 0 && (
          <table>
            <thead>
              <tr>
                <th>Référence</th>
                <th>Type</th>
                <th>Créée par</th>
                <th>Assignée à</th>
                <th>Statut</th>
                <th>Date</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {requests.map((req) => {
                const assignedToMe = req.assignedTo === user?.id || req.assignee?.id === user?.id;
                return (
                  <tr key={req.id}>
                    <td>{req.reference}</td>
                    <td>{req.workflowType}</td>
                    <td>{req.creator?.fullName || '-'}</td>
                    <td>
                      {req.assignee?.fullName || req.assignedTo || '-'}
                      {assignedToMe ? ' (moi)' : ''}
                    </td>
                    <td><span className={`status status-${req.status}`}>{req.status}</span></td>
                    <td>{new Date(req.createdAt).toLocaleDateString()}</td>
                    <td><Link to={`/requests/${req.id}`} className="text-blue-600">Voir</Link></td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
};

export default RequestList;
